contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: attempt to deposit NFTs and base tokens and assert the observed invariants
    function run(uint256[] calldata tokenIds, uint256 baseTokenAmount, address baseToken) public payable {
        // If sending ETH to c as part of deposit, we must have this contract hold enough ETH
        if (baseToken == address(0)) {
            // require we have the ETH available to forward
            require(address(this).balance >= baseTokenAmount, "insufficient test ETH");
        }

        // Observe balances/values before the state-changing call
        uint256 beforeNftBalance = ERC721(c.nft()).balanceOf(address(c));
        uint256 beforeBaseBalance;
        if (baseToken == address(0)) {
            beforeBaseBalance = address(c).balance;
        } else {
            beforeBaseBalance = ERC20(baseToken).balanceOf(address(c));
        }

        bool reverted;
        // Make the deposit call on c. Must be a top-level statement.
        try c.deposit{value: baseToken == address(0) ? baseTokenAmount : 0}(tokenIds, baseTokenAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after-values (only via public interface)
        uint256 afterNftBalance = ERC721(c.nft()).balanceOf(address(c));
        uint256 afterBaseBalance;
        if (baseToken == address(0)) {
            afterBaseBalance = address(c).balance;
        } else {
            afterBaseBalance = ERC20(baseToken).balanceOf(address(c));
        }

        // General rule: if deposit did not revert then NFT balance increased by exactly tokenIds.length
        // and base token balance increased by exactly baseTokenAmount; if it reverted, no guarantee so we only assert the implication
        assert(reverted || (afterNftBalance == beforeNftBalance + tokenIds.length && afterBaseBalance == beforeBaseBalance + baseTokenAmount));
    }

    receive() external payable {}
}

