contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test: caller supplies NFT array, tokenAmount, and if ETH should be withdrawn the test contract
    // must hold at least `ethFund` so it can supply it when invoking c.withdraw (the call forwards no ETH to c,
    // but the pool will send ETH back to this contract). We therefore require address(this).balance >= ethFund.
    function run(address nftAddress, uint256[] calldata tokenIds, address token, uint256 tokenAmount, uint256 ethFund) public payable {
        // ensure the test contract has enough ETH to receive refunds or to satisfy any preconditions in the environment
        require(address(this).balance >= ethFund, "insufficient test ETH balance");

        // Observe pre-state via public getters only
        uint256 beforeNftBalance = ERC721(nftAddress).balanceOf(address(c));

        address base = c.baseToken();
        uint256 beforeBaseBalance;
        if (base == address(0)) {
            beforeBaseBalance = address(c).balance;
        } else {
            beforeBaseBalance = ERC20(base).balanceOf(address(c));
        }

        bool reverted;
        // Top-level state-changing call on c: try withdraw. Must be direct.
        try c.withdraw(nftAddress, tokenIds, token, tokenAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe post-state
        uint256 afterNftBalance = ERC721(nftAddress).balanceOf(address(c));
        uint256 afterBaseBalance;
        if (base == address(0)) {
            afterBaseBalance = address(c).balance;
        } else {
            afterBaseBalance = ERC20(base).balanceOf(address(c));
        }

        // General rule: either call reverted, or the pool's NFT balance decreased by tokenIds.length
        // and the pool's base-token balance decreased by tokenAmount (observed via public balances).
        // (We avoid underflow by comparing with <= when appropriate.)
        assert(
            reverted || (
                afterNftBalance + tokenIds.length == beforeNftBalance &&
                (beforeBaseBalance >= tokenAmount ? afterBaseBalance + tokenAmount == beforeBaseBalance : false)
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We check that when buy(...) does not revert, the pool's NFT balance decreases by tokenIds.length
    // and the pool's virtualBaseTokenReserves increases by (netInputAmount - feeAmount - protocolFeeAmount)
    // We cannot read internal virtualBaseTokenReserves directly, but we can observe price() and address(c).balance
    // so we record price and balance before and after, and assert consistency with buyQuote result.

    function run(uint256[] calldata tokenIds, uint256[] calldata tokenWeights, bytes32[] calldata proof, bool[] calldata flags, uint256 ethAmount) public payable {
        // Ensure we can send ETH if needed
        require(address(this).balance >= ethAmount, "Insufficient test balance");

        // Prepare MerkleMultiProof struct in memory as required by c.buy
        C.MerkleMultiProof memory mp;
        mp.proof = proof;
        mp.flags = flags;

        // Read pre-state
        uint256 prePrice = c.price();
        uint256 preBalance = address(c).balance;

        // Compute weightSum by calling sumWeightsAndValidateProof (view) to get intended outputAmount
        // This will revert if proof invalid; we want to capture both revert and non-revert behaviours
        bool reverted = false;
        uint256 weightSum = 0;
        try c.sumWeightsAndValidateProof(tokenIds, tokenWeights, mp) returns (uint256 sum) {
            weightSum = sum;
        } catch {
            reverted = true;
        }

        // Also get quoted amounts for buying; this is view and will not modify state
        (uint256 netInputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.buyQuote(weightSum);

        // Now attempt the state-changing buy call, sending ETH if ethAmount > 0
        bool buyReverted = false;
        try c.buy{value: ethAmount}(tokenIds, tokenWeights, mp) returns (uint256 netIn, uint256 feeA, uint256 protoFeeA) {
            // success - values returned available but we won't rely solely on them
        } catch {
            buyReverted = true;
        }

        // Read post-state
        uint256 postPrice = c.price();
        uint256 postBalance = address(c).balance;

        // General property to assert:
        // If buy did NOT revert, then:
        // 1) The pool's NFT balance (as implied by price formula change and virtual reserves) must reflect that virtualNftReserves decreased by weightSum.
        //    We observe price = (virtualBaseTokenReserves * 10^exponent) / virtualNftReserves.
        //    After a successful buy, virtualNftReserves decreases by weightSum and virtualBaseTokenReserves increases by (netInputAmount - feeAmount - protocolFeeAmount).
        //    Thus price after should equal ((vb + deltaVB) * factor) / (vn - weightSum).
        // 2) The contract's ETH balance must have increased by protocolFeeAmount if baseToken == address(0) (handled by factory transfer), or decreased/unchanged otherwise.
        // Because we cannot branch on c.baseToken() inside assert, we express a weaker but general relation: if buy succeeded then postPrice * (uint256(1)) must be consistent with buyQuote result.

        // We craft a relation using multiplication to avoid division inside assert: for exponent unknown, use ratio comparison via buyQuote math
        // Using buyQuote: inputAmount = mulDivUp(outputAmount, virtualBaseTokenReserves, (virtualNftReserves - outputAmount))
        // But we cannot access virtual reserves directly. Instead we assert that when buy succeeded, weightSum>0 implies postPrice != prePrice OR address(c).balance changed appropriately.

        // Final single assert: if buy succeeded then either weightSum == 0 (no NFTs moved) or postBalance == preBalance + protocolFeeAmount || postPrice != prePrice
        // This asserts that a successful buy with nonzero weight either changed the pool's observable price or pool ETH balance changed by protocol fee — a general invariant tying state change to observable effects.

        assert( buyReverted || (weightSum == 0 || postBalance == preBalance + protocolFeeAmount || postPrice != prePrice) );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry that checks the relation between success of sumWeightsAndValidateProof
    // and the returned sum: returned sum equals the arithmetic sum of the tokenWeights array,
    // and is zero exactly when every tokenWeight is zero.
    function run(uint256[] calldata tokenIds, uint256[] calldata tokenWeights, bytes32[] calldata proof, bool[] calldata flags) public payable {
        require(tokenIds.length == tokenWeights.length, "len");

        // Build MerkleMultiProof in memory
        C.MerkleMultiProof memory mp;
        mp.proof = proof;
        mp.flags = flags;

        bool reverted = false;
        uint256 sum = 0;
        try c.sumWeightsAndValidateProof(tokenIds, tokenWeights, mp) returns (uint256 s) {
            sum = s;
        } catch {
            reverted = true;
        }

        // Compute plain sum locally (will not overflow in practice for reasonable inputs; use unchecked to match Solidity behavior)
        uint256 localSum = 0;
        for (uint256 i = 0; i < tokenWeights.length; i++) {
            unchecked { localSum += tokenWeights[i]; }
        }

        // Assert a general rule: if the call did not revert, the returned sum equals the local arithmetic sum
        // and moreover returned sum == 0 iff all tokenWeights are zero.
        assert(reverted || (sum == localSum && ((sum == 0) == (localSum == 0))));
    }

    receive() external payable {}
}

